        { k: "adresat", l: "Кому адресовано", p: "начальнику ОМВД России по району ..." },
        { k: "zayavitel", l: "ФИО, дата рождения заявителя", p: "Петров Пётр Петрович, 05.05.1985" },
        { k: "adres", l: "Адрес и телефон заявителя", p: "г. Москва, ул. ..., д. ..., тел. ..." },
        { k: "sobitie", l: "Что произошло (время, место, обстоятельства)", type: "textarea", p: "08.10.2026 около 20:00 неустановленное лицо тайно похитило из квартиры по адресу ... принадлежащее мне имущество" },
        { k: "svedeniya", l: "Известные сведения о лице, совершившем деяние", p: "неизвестно" }
